beforeSaveCustomScript:
ifThen(!name, name = string\concatenate('Reservation - ', unit.name, ' - ', contact.name));
ifThen(unitId && status == 'Active', record\update('Unit', unitId, 'status', 'Reserved'));
ifThen(unitId && (status == 'Cancelled' || status == 'Expired') && record\attribute('Unit', unitId, 'status') == 'Reserved', record\update('Unit', unitId, 'status', 'Available'));
